// Cloudflare Worker: يخدم الواجهة + بروكسي للبيانات (يتجاوز CORS ويجرّب عدة مصادر)
// هذا الملف هو القالب؛ شغّل `npm run build` لتوليد src/worker.js (ملف واحد جاهز للصق في لوحة Cloudflare)

const HTML = "<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>محلل الذهب والبتكوين</title>\n<style>\n:root{\n  --bg:#0b0f17;--card:#131a26;--card2:#1a2333;--line:#243049;--tx:#e6edf7;--mut:#8b9bb4;\n  --up:#22c55e;--dn:#ef4444;--gold:#f5b942;--blue:#4c9aff;--warn:#f59e0b;\n}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml{-webkit-text-size-adjust:100%}\nbody{background:var(--bg);color:var(--tx);font-family:system-ui,-apple-system,\"Segoe UI\",Tahoma,Arial,sans-serif;line-height:1.55;padding-bottom:40px}\n.wrap{max-width:980px;margin:0 auto;padding:0 12px}\nheader{position:sticky;top:0;z-index:10;background:rgba(11,15,23,.94);backdrop-filter:blur(8px);border-bottom:1px solid var(--line);padding:10px 0}\n.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}\n.title{font-weight:800;font-size:17px;margin-inline-end:auto}\n.title b{color:var(--gold)}\n.seg{display:flex;background:var(--card);border:1px solid var(--line);border-radius:10px;overflow:hidden}\n.seg button{background:none;border:0;color:var(--mut);padding:7px 12px;font:inherit;font-size:13px;cursor:pointer}\n.seg button.on{background:var(--blue);color:#fff;font-weight:700}\n.iconbtn{background:var(--card);border:1px solid var(--line);color:var(--tx);border-radius:10px;padding:7px 12px;font:inherit;font-size:13px;cursor:pointer}\n.pricebar{display:flex;align-items:baseline;gap:12px;padding:12px 0 4px;flex-wrap:wrap}\n.price{font-size:30px;font-weight:800;direction:ltr;unicode-bidi:isolate}\n.chg{font-size:14px;direction:ltr;unicode-bidi:isolate}\n.meta{color:var(--mut);font-size:12px;margin-inline-start:auto}\n.tabs{display:flex;gap:6px;overflow-x:auto;padding:8px 0;scrollbar-width:none}\n.tabs::-webkit-scrollbar{display:none}\n.tabs button{flex:0 0 auto;background:var(--card);border:1px solid var(--line);color:var(--mut);padding:8px 16px;border-radius:999px;font:inherit;font-size:14px;cursor:pointer}\n.tabs button.on{background:var(--gold);border-color:var(--gold);color:#111;font-weight:800}\n.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px;margin:10px 0}\n.card h3{font-size:15px;margin-bottom:10px;color:var(--gold)}\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px}\n.ltr{direction:ltr;unicode-bidi:isolate;display:inline-block}\n.mut{color:var(--mut)}.up{color:var(--up)}.dn{color:var(--dn)}.warn{color:var(--warn)}\n.tag{display:inline-block;padding:2px 10px;border-radius:999px;font-size:12px;font-weight:700}\n.sbuy2{background:#14532d;color:#86efac}.sbuy{background:#166534;color:#bbf7d0}.lbuy{background:#1d3b2a;color:#86efac}\n.ssell2{background:#7f1d1d;color:#fca5a5}.ssell{background:#991b1b;color:#fecaca}.lsell{background:#3b1d1d;color:#fca5a5}\n.neutral{background:#2a3347;color:#cbd5e1}\n.hero{text-align:center}\n.hero .big{font-size:30px;font-weight:900;margin:6px 0}\n.gauge{position:relative;height:16px;border-radius:99px;background:linear-gradient(90deg,#991b1b,#ef4444 25%,#475569 50%,#22c55e 75%,#166534);margin:16px 6px 6px}\n.gauge i{position:absolute;top:-6px;width:4px;height:28px;background:#fff;border-radius:2px;transform:translateX(-50%);box-shadow:0 0 0 2px #000a}\n.glab{display:flex;justify-content:space-between;font-size:11px;color:var(--mut);padding:0 6px}\n.kv{display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-bottom:1px dashed var(--line);font-size:14px}\n.kv:last-child{border-bottom:0}\n.bar{height:6px;border-radius:9px;background:var(--card2);overflow:hidden;margin-top:4px;position:relative}\n.bar>span{position:absolute;top:0;bottom:0}\ntable{width:100%;border-collapse:collapse;font-size:13px}\nth,td{padding:7px 6px;text-align:start;border-bottom:1px solid var(--line)}\nth{color:var(--mut);font-weight:600;font-size:12px}\n.heat{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:6px}\n.heat div{border-radius:10px;padding:8px;font-size:12px;text-align:center;border:1px solid #0003}\n.heat b{display:block;font-size:11px;font-weight:600;opacity:.9}\ncanvas{width:100%;height:340px;display:block;border-radius:10px;background:#0e1420}\n.err{background:#3b1d1d;border:1px solid #7f1d1d;color:#fecaca;padding:12px;border-radius:12px;margin:10px 0}\n.loading{text-align:center;color:var(--mut);padding:40px 0}\ninput{background:var(--card2);border:1px solid var(--line);color:var(--tx);border-radius:10px;padding:9px 10px;font:inherit;width:100%;direction:ltr;text-align:left}\nlabel{font-size:12px;color:var(--mut);display:block;margin-bottom:4px}\n.warnbox{font-size:12px;color:var(--mut);border:1px solid var(--line);border-radius:12px;padding:10px;margin-top:14px;background:var(--card)}\n.pill{display:inline-block;padding:1px 8px;border-radius:8px;font-size:11px;background:var(--card2);color:var(--mut);margin-inline-start:6px}\n.kz{display:flex;justify-content:space-between;align-items:center;padding:9px 10px;border-radius:10px;background:var(--card2);margin:6px 0;font-size:14px}\n.kz.on{outline:2px solid var(--gold);background:#2b2412}\n</style>\n</head>\n<body>\n<header>\n  <div class=\"wrap\">\n    <div class=\"row\">\n      <div class=\"title\">📊 محلل <b>الذهب</b> والبتكوين</div>\n      <div class=\"seg\" id=\"symSeg\"></div>\n      <div class=\"seg\" id=\"tfSeg\"></div>\n      <button class=\"iconbtn\" id=\"refresh\">⟳ تحديث</button>\n    </div>\n  </div>\n</header>\n<div class=\"wrap\">\n  <div class=\"pricebar\">\n    <div class=\"price\" id=\"price\">—</div>\n    <div class=\"chg\" id=\"chg\"></div>\n    <div class=\"meta\" id=\"meta\"></div>\n  </div>\n  <div class=\"tabs\" id=\"tabs\"></div>\n  <div id=\"view\"><div class=\"loading\">جارٍ تحميل البيانات…</div></div>\n  <div class=\"warnbox\">⚠️ أداة تحليل فني تعليمية للمساعدة في اتخاذ القرار وليست نصيحة مالية. لا توجد أي أداة تضمن الربح؛ التداول — خصوصاً المضاربة والرافعة المالية — ينطوي على مخاطر عالية قد تؤدي لخسارة كامل رأس المال. التزم بوقف الخسارة ولا تخاطر بأكثر مما تتحمل خسارته. الذهب يُحلَّل عبر PAXG (رمز مدعوم بالذهب الفعلي) وقد يختلف قليلاً عن سعر XAUUSD.</div>\n</div>\n<script>\n/* محرك التحليل — يعمل في المتصفح وفي Node للاختبار\n * candles: [{t,o,h,l,c,v}] مرتبة من الأقدم للأحدث\n */\n(function (root) {\n  const A = {};\n  const last = (a, k = 1) => a[a.length - k];\n  const clamp = (x, a, b) => Math.max(a, Math.min(b, x));\n  const sum = (a) => a.reduce((x, y) => x + y, 0);\n\n  /* ================= المؤشرات الأساسية ================= */\n  A.ema = (v, p) => {\n    const k = 2 / (p + 1);\n    const o = [];\n    let e = v[0];\n    for (let i = 0; i < v.length; i++) {\n      e = i === 0 ? v[0] : v[i] * k + e * (1 - k);\n      o.push(e);\n    }\n    return o;\n  };\n\n  A.sma = (v, p) => {\n    const o = new Array(v.length).fill(null);\n    let s = 0;\n    for (let i = 0; i < v.length; i++) {\n      s += v[i];\n      if (i >= p) s -= v[i - p];\n      if (i >= p - 1) o[i] = s / p;\n    }\n    return o;\n  };\n\n  A.rsi = (c, p = 14) => {\n    const o = new Array(c.length).fill(null);\n    if (c.length <= p) return o;\n    let g = 0, l = 0;\n    for (let i = 1; i <= p; i++) {\n      const d = c[i] - c[i - 1];\n      if (d >= 0) g += d; else l -= d;\n    }\n    g /= p; l /= p;\n    o[p] = l === 0 ? 100 : 100 - 100 / (1 + g / l);\n    for (let i = p + 1; i < c.length; i++) {\n      const d = c[i] - c[i - 1];\n      g = (g * (p - 1) + Math.max(d, 0)) / p;\n      l = (l * (p - 1) + Math.max(-d, 0)) / p;\n      o[i] = l === 0 ? 100 : 100 - 100 / (1 + g / l);\n    }\n    return o;\n  };\n\n  A.trueRange = (cs) =>\n    cs.map((x, i) => {\n      if (i === 0) return x.h - x.l;\n      const pc = cs[i - 1].c;\n      return Math.max(x.h - x.l, Math.abs(x.h - pc), Math.abs(x.l - pc));\n    });\n\n  A.atr = (cs, p = 14) => {\n    const tr = A.trueRange(cs);\n    const o = new Array(cs.length).fill(null);\n    if (cs.length < p) return o;\n    let a = sum(tr.slice(0, p)) / p;\n    o[p - 1] = a;\n    for (let i = p; i < cs.length; i++) {\n      a = (a * (p - 1) + tr[i]) / p;\n      o[i] = a;\n    }\n    return o;\n  };\n\n  A.macd = (c, f = 12, s = 26, sg = 9) => {\n    const ef = A.ema(c, f), es = A.ema(c, s);\n    const line = c.map((_, i) => ef[i] - es[i]);\n    const signal = A.ema(line, sg);\n    const hist = line.map((x, i) => x - signal[i]);\n    return { line, signal, hist };\n  };\n\n  A.bollinger = (c, p = 20, k = 2) => {\n    const mid = A.sma(c, p);\n    const up = [], lo = [], pb = [], bw = [];\n    for (let i = 0; i < c.length; i++) {\n      if (mid[i] == null) { up.push(null); lo.push(null); pb.push(null); bw.push(null); continue; }\n      const sl = c.slice(i - p + 1, i + 1);\n      const sd = Math.sqrt(sum(sl.map((x) => (x - mid[i]) ** 2)) / p);\n      up.push(mid[i] + k * sd);\n      lo.push(mid[i] - k * sd);\n      pb.push(up[i] === lo[i] ? 0.5 : (c[i] - lo[i]) / (up[i] - lo[i]));\n      bw.push((up[i] - lo[i]) / mid[i]);\n    }\n    return { mid, up, lo, pb, bw };\n  };\n\n  A.stoch = (cs, p = 14, sk = 3, sd = 3) => {\n    const raw = cs.map((x, i) => {\n      if (i < p - 1) return null;\n      const sl = cs.slice(i - p + 1, i + 1);\n      const hh = Math.max(...sl.map((y) => y.h));\n      const ll = Math.min(...sl.map((y) => y.l));\n      return hh === ll ? 50 : ((x.c - ll) / (hh - ll)) * 100;\n    });\n    const sm = (arr, n) =>\n      arr.map((_, i) => {\n        if (i < n - 1 || arr.slice(i - n + 1, i + 1).some((v) => v == null)) return null;\n        return sum(arr.slice(i - n + 1, i + 1)) / n;\n      });\n    const k = sm(raw, sk);\n    const d = sm(k, sd);\n    return { k, d };\n  };\n\n  A.supertrend = (cs, p = 10, m = 3) => {\n    const atr = A.atr(cs, p);\n    const trend = new Array(cs.length).fill(0);\n    const line = new Array(cs.length).fill(null);\n    let fu = null, fl = null, dir = 1;\n    for (let i = 0; i < cs.length; i++) {\n      if (atr[i] == null) continue;\n      const hl2 = (cs[i].h + cs[i].l) / 2;\n      let bu = hl2 + m * atr[i];\n      let bl = hl2 - m * atr[i];\n      if (fu == null) { fu = bu; fl = bl; dir = cs[i].c >= hl2 ? 1 : -1; }\n      else {\n        const pc = cs[i - 1].c;\n        bu = bu < fu || pc > fu ? bu : fu;\n        bl = bl > fl || pc < fl ? bl : fl;\n        if (dir === 1 && cs[i].c < fl) dir = -1;\n        else if (dir === -1 && cs[i].c > fu) dir = 1;\n        fu = bu; fl = bl;\n      }\n      trend[i] = dir;\n      line[i] = dir === 1 ? fl : fu;\n    }\n    return { trend, line };\n  };\n\n  A.adx = (cs, p = 14) => {\n    const n = cs.length;\n    const adx = new Array(n).fill(null), pdi = new Array(n).fill(null), mdi = new Array(n).fill(null);\n    if (n < p * 2 + 1) return { adx, pdi, mdi };\n    const tr = A.trueRange(cs);\n    const pdm = [0], mdm = [0];\n    for (let i = 1; i < n; i++) {\n      const up = cs[i].h - cs[i - 1].h, dn = cs[i - 1].l - cs[i].l;\n      pdm.push(up > dn && up > 0 ? up : 0);\n      mdm.push(dn > up && dn > 0 ? dn : 0);\n    }\n    let str = sum(tr.slice(1, p + 1)), sp = sum(pdm.slice(1, p + 1)), sm = sum(mdm.slice(1, p + 1));\n    const dx = [];\n    for (let i = p; i < n; i++) {\n      if (i > p) {\n        str = str - str / p + tr[i];\n        sp = sp - sp / p + pdm[i];\n        sm = sm - sm / p + mdm[i];\n      }\n      const pi = (sp / str) * 100, mi = (sm / str) * 100;\n      pdi[i] = pi; mdi[i] = mi;\n      dx.push({ i, v: pi + mi === 0 ? 0 : (Math.abs(pi - mi) / (pi + mi)) * 100 });\n    }\n    let a = sum(dx.slice(0, p).map((d) => d.v)) / p;\n    adx[dx[p - 1].i] = a;\n    for (let j = p; j < dx.length; j++) {\n      a = (a * (p - 1) + dx[j].v) / p;\n      adx[dx[j].i] = a;\n    }\n    return { adx, pdi, mdi };\n  };\n\n  A.vwap = (cs, tf) => {\n    const intraday = tf === \"15m\" || tf === \"1h\";\n    let start = Math.max(0, cs.length - 30);\n    if (intraday) {\n      const dayStart = Math.floor(last(cs).t / 86400000) * 86400000;\n      const idx = cs.findIndex((x) => x.t >= dayStart);\n      start = cs.length - idx >= 4 ? idx : Math.max(0, cs.length - 24);\n    }\n    let pv = 0, vv = 0;\n    for (let i = start; i < cs.length; i++) {\n      const tp = (cs[i].h + cs[i].l + cs[i].c) / 3;\n      pv += tp * cs[i].v; vv += cs[i].v;\n    }\n    return vv ? pv / vv : last(cs).c;\n  };\n\n  /* ================= SMC / ICT ================= */\n  A.swings = (cs, n = 3) => {\n    const out = [];\n    for (let i = n; i < cs.length - n; i++) {\n      let hi = true, lo = true;\n      for (let j = 1; j <= n; j++) {\n        if (cs[i].h <= cs[i - j].h || cs[i].h <= cs[i + j].h) hi = false;\n        if (cs[i].l >= cs[i - j].l || cs[i].l >= cs[i + j].l) lo = false;\n      }\n      if (hi) out.push({ i, p: cs[i].h, type: \"H\" });\n      if (lo) out.push({ i, p: cs[i].l, type: \"L\" });\n    }\n    return out;\n  };\n\n  A.structure = (cs, sw) => {\n    const H = sw.filter((s) => s.type === \"H\"), L = sw.filter((s) => s.type === \"L\");\n    const price = last(cs).c;\n    let trend = \"range\";\n    if (H.length >= 2 && L.length >= 2) {\n      const hh = last(H).p > last(H, 2).p, hl = last(L).p > last(L, 2).p;\n      if (hh && hl) trend = \"bull\";\n      else if (!hh && !hl) trend = \"bear\";\n    }\n    let event = null;\n    const lastH = H.length ? last(H) : null, lastL = L.length ? last(L) : null;\n    const look = Math.max(0, cs.length - 10);\n    if (lastH) {\n      const from = Math.max(lastH.i + 1, look);\n      for (let i = from; i < cs.length; i++) if (cs[i].c > lastH.p) { event = { dir: 1, kind: trend === \"bear\" ? \"CHOCH\" : \"BOS\", level: lastH.p, age: cs.length - 1 - i }; break; }\n    }\n    if (lastL) {\n      const from = Math.max(lastL.i + 1, look);\n      for (let i = from; i < cs.length; i++) if (cs[i].c < lastL.p) {\n        const ev = { dir: -1, kind: trend === \"bull\" ? \"CHOCH\" : \"BOS\", level: lastL.p, age: cs.length - 1 - i };\n        if (!event || ev.age < event.age) event = ev;\n        break;\n      }\n    }\n    return { trend, event, lastH, lastL, price };\n  };\n\n  A.fvgs = (cs, atr) => {\n    const out = [];\n    for (let i = 2; i < cs.length; i++) {\n      const a = cs[i - 2], c = cs[i];\n      let g = null;\n      if (a.h < c.l) g = { dir: 1, lo: a.h, hi: c.l, i };\n      else if (a.l > c.h) g = { dir: -1, lo: c.h, hi: a.l, i };\n      if (!g || g.hi - g.lo < 0.1 * atr) continue;\n      let filled = false;\n      for (let j = i + 1; j < cs.length; j++) {\n        if (g.dir === 1 && cs[j].l <= g.lo) { filled = true; break; }\n        if (g.dir === -1 && cs[j].h >= g.hi) { filled = true; break; }\n      }\n      if (!filled) out.push(g);\n    }\n    return out.slice(-8);\n  };\n\n  A.orderBlocks = (cs, atrArr) => {\n    const out = [];\n    const start = Math.max(1, cs.length - 200);\n    for (let i = start; i < cs.length - 3; i++) {\n      const a = atrArr[i] || atrArr.find((x) => x) || 1;\n      const bear = cs[i].c < cs[i].o, bull = cs[i].c > cs[i].o;\n      const nx = cs.slice(i + 1, i + 4);\n      if (bear && cs[i + 1].c > cs[i + 1].o && Math.max(...nx.map((x) => x.h)) - cs[i].h > 1.2 * a)\n        out.push({ dir: 1, lo: cs[i].l, hi: cs[i].h, i });\n      else if (bull && cs[i + 1].c < cs[i + 1].o && cs[i].l - Math.min(...nx.map((x) => x.l)) > 1.2 * a)\n        out.push({ dir: -1, lo: cs[i].l, hi: cs[i].h, i });\n    }\n    return out\n      .filter((ob) => {\n        for (let j = ob.i + 4; j < cs.length; j++) {\n          if (ob.dir === 1 && cs[j].c < ob.lo) return false;\n          if (ob.dir === -1 && cs[j].c > ob.hi) return false;\n        }\n        return true;\n      })\n      .slice(-6);\n  };\n\n  A.liquidity = (cs, sw, atr) => {\n    const H = sw.filter((s) => s.type === \"H\").slice(-10), L = sw.filter((s) => s.type === \"L\").slice(-10);\n    const tol = 0.15 * atr;\n    const eqh = [], eql = [];\n    for (let a = 0; a < H.length; a++) for (let b = a + 1; b < H.length; b++)\n      if (Math.abs(H[a].p - H[b].p) <= tol) {\n        const lvl = (H[a].p + H[b].p) / 2;\n        const swept = cs.slice(H[b].i + 1).some((x) => x.h > lvl + tol);\n        if (!swept) eqh.push({ level: lvl });\n      }\n    for (let a = 0; a < L.length; a++) for (let b = a + 1; b < L.length; b++)\n      if (Math.abs(L[a].p - L[b].p) <= tol) {\n        const lvl = (L[a].p + L[b].p) / 2;\n        const swept = cs.slice(L[b].i + 1).some((x) => x.l < lvl - tol);\n        if (!swept) eql.push({ level: lvl });\n      }\n    // كنس السيولة في آخر 5 شموع\n    let sweep = null;\n    const n = cs.length;\n    for (let k = n - 1; k >= n - 5 && !sweep; k--) {\n      const c = cs[k];\n      for (const s of sw.filter((x) => x.i < k - 1 && x.i > k - 50).reverse()) {\n        if (s.type === \"H\" && c.h > s.p && c.c < s.p) { sweep = { dir: -1, level: s.p, age: n - 1 - k }; break; }\n        if (s.type === \"L\" && c.l < s.p && c.c > s.p) { sweep = { dir: 1, level: s.p, age: n - 1 - k }; break; }\n      }\n    }\n    return { eqh: eqh.slice(-3), eql: eql.slice(-3), sweep };\n  };\n\n  A.premiumDiscount = (cs, sw) => {\n    const rec = sw.filter((s) => s.i > cs.length - 80);\n    const hs = rec.filter((s) => s.type === \"H\"), ls = rec.filter((s) => s.type === \"L\");\n    const hi = hs.length ? Math.max(...hs.map((s) => s.p)) : Math.max(...cs.slice(-80).map((x) => x.h));\n    const lo = ls.length ? Math.min(...ls.map((s) => s.p)) : Math.min(...cs.slice(-80).map((x) => x.l));\n    const price = last(cs).c;\n    const eq = (hi + lo) / 2;\n    return { hi, lo, eq, pos: hi === lo ? 0.5 : clamp((price - lo) / (hi - lo), 0, 1), zone: price > eq ? \"premium\" : \"discount\" };\n  };\n\n  A.divergence = (cs, rsi, sw) => {\n    const n = cs.length;\n    const H = sw.filter((s) => s.type === \"H\" && rsi[s.i] != null).slice(-2);\n    const L = sw.filter((s) => s.type === \"L\" && rsi[s.i] != null).slice(-2);\n    if (L.length === 2 && n - 1 - L[1].i <= 30 && L[1].p < L[0].p && rsi[L[1].i] > rsi[L[0].i] + 1)\n      return { dir: 1, text: \"دايفرجنس صاعد (قاع أدنى بسعر وأعلى بالـRSI)\" };\n    if (H.length === 2 && n - 1 - H[1].i <= 30 && H[1].p > H[0].p && rsi[H[1].i] < rsi[H[0].i] - 1)\n      return { dir: -1, text: \"دايفرجنس هابط (قمة أعلى بسعر وأدنى بالـRSI)\" };\n    return null;\n  };\n\n  A.fibonacci = (cs) => {\n    const sl = cs.slice(-100);\n    let hiI = 0, loI = 0;\n    sl.forEach((x, i) => { if (x.h > sl[hiI].h) hiI = i; if (x.l < sl[loI].l) loI = i; });\n    const hi = sl[hiI].h, lo = sl[loI].l, up = loI < hiI;\n    const r = hi - lo;\n    const lv = (f) => (up ? hi - r * f : lo + r * f);\n    return {\n      dir: up ? 1 : -1, hi, lo,\n      levels: [0.236, 0.382, 0.5, 0.618, 0.786].map((f) => ({ f, p: lv(f) })),\n      ext: [1.272, 1.618].map((f) => ({ f, p: up ? lo + r * f : hi - r * f })),\n    };\n  };\n\n  A.pivots = (c) => {\n    const P = (c.h + c.l + c.c) / 3, r = c.h - c.l;\n    return { P, R1: 2 * P - c.l, R2: P + r, R3: c.h + 2 * (P - c.l), S1: 2 * P - c.h, S2: P - r, S3: c.l - 2 * (c.h - P) };\n  };\n\n  A.supportResistance = (sw, price, atr) => {\n    const pts = sw.map((s) => s.p).sort((a, b) => a - b);\n    const cl = [];\n    pts.forEach((p) => {\n      const c = cl.find((x) => Math.abs(x.p - p) <= 0.5 * atr);\n      if (c) { c.p = (c.p * c.n + p) / (c.n + 1); c.n++; } else cl.push({ p, n: 1 });\n    });\n    const above = cl.filter((x) => x.p > price).sort((a, b) => a.p - b.p).slice(0, 3);\n    const below = cl.filter((x) => x.p <= price).sort((a, b) => b.p - a.p).slice(0, 3);\n    return { resistance: above, support: below };\n  };\n\n  /* ================= الأنماط ================= */\n  A.candlePatterns = (cs, atr) => {\n    const out = [];\n    const n = cs.length;\n    for (let age = 0; age < 3; age++) {\n      const i = n - 1 - age;\n      if (i < 6) break;\n      const x = cs[i], p = cs[i - 1];\n      const body = Math.abs(x.c - x.o), range = x.h - x.l || 1e-9;\n      const up = x.h - Math.max(x.o, x.c), lw = Math.min(x.o, x.c) - x.l;\n      const downtrend = cs[i - 1].c < cs[i - 5].c, uptrend = cs[i - 1].c > cs[i - 5].c;\n      const push = (name, dir) => out.push({ name, dir, age });\n      if (body <= 0.1 * range) push(\"دوجي (تردد)\", 0);\n      if (body >= 0.85 * range && range > 0.8 * atr) push(x.c > x.o ? \"ماروبوزو صاعد\" : \"ماروبوزو هابط\", x.c > x.o ? 1 : -1);\n      if (body > 0 && lw >= 2 * body && up <= 0.35 * body + 0.05 * range && downtrend) push(\"مطرقة (Hammer)\", 1);\n      if (body > 0 && up >= 2 * body && lw <= 0.35 * body + 0.05 * range && uptrend) push(\"نجمة الرجم (Shooting Star)\", -1);\n      if (body <= range / 3 && lw >= (2 / 3) * range) push(\"بين بار صاعد\", 1);\n      if (body <= range / 3 && up >= (2 / 3) * range) push(\"بين بار هابط\", -1);\n      if (p.c < p.o && x.c > x.o && x.o <= p.c && x.c >= p.o) push(\"ابتلاع صاعد\", 1);\n      if (p.c > p.o && x.c < x.o && x.o >= p.c && x.c <= p.o) push(\"ابتلاع هابط\", -1);\n    }\n    return out;\n  };\n\n  A.chartPatterns = (cs, sw, atr) => {\n    const out = [];\n    const n = cs.length, price = last(cs).c;\n    const H = sw.filter((s) => s.type === \"H\"), L = sw.filter((s) => s.type === \"L\");\n    const lowBetween = (a, b) => Math.min(...cs.slice(a.i, b.i + 1).map((x) => x.l));\n    const highBetween = (a, b) => Math.max(...cs.slice(a.i, b.i + 1).map((x) => x.h));\n    if (H.length >= 2) {\n      const a = last(H, 2), b = last(H);\n      if (n - b.i < 60 && Math.abs(a.p - b.p) <= 0.6 * atr && b.i - a.i >= 5) {\n        const neck = lowBetween(a, b);\n        out.push({ name: \"قمة مزدوجة\", dir: -1, status: price < neck ? \"مكتمل (كسر خط العنق)\" : \"قيد التشكل\", level: neck });\n      }\n    }\n    if (L.length >= 2) {\n      const a = last(L, 2), b = last(L);\n      if (n - b.i < 60 && Math.abs(a.p - b.p) <= 0.6 * atr && b.i - a.i >= 5) {\n        const neck = highBetween(a, b);\n        out.push({ name: \"قاع مزدوج\", dir: 1, status: price > neck ? \"مكتمل (كسر خط العنق)\" : \"قيد التشكل\", level: neck });\n      }\n    }\n    if (H.length >= 3) {\n      const [s1, hd, s2] = H.slice(-3);\n      if (n - s2.i < 80 && hd.p > s1.p && hd.p > s2.p && Math.abs(s1.p - s2.p) <= 1.2 * atr) {\n        const neck = (lowBetween(s1, hd) + lowBetween(hd, s2)) / 2;\n        out.push({ name: \"رأس وكتفين\", dir: -1, status: price < neck ? \"مكتمل\" : \"قيد التشكل\", level: neck });\n      }\n    }\n    if (L.length >= 3) {\n      const [s1, hd, s2] = L.slice(-3);\n      if (n - s2.i < 80 && hd.p < s1.p && hd.p < s2.p && Math.abs(s1.p - s2.p) <= 1.2 * atr) {\n        const neck = (highBetween(s1, hd) + highBetween(hd, s2)) / 2;\n        out.push({ name: \"رأس وكتفين معكوس\", dir: 1, status: price > neck ? \"مكتمل\" : \"قيد التشكل\", level: neck });\n      }\n    }\n    return out;\n  };\n\n  /* ================= التحليل الكامل لإطار واحد ================= */\n  A.analyze = (cs, tf, dailyCs) => {\n    if (!cs || cs.length < 60) throw new Error(\"بيانات غير كافية\");\n    const close = cs.map((x) => x.c);\n    const price = last(close);\n    const n = cs.length;\n\n    const e9 = A.ema(close, 9), e21 = A.ema(close, 21), e50 = A.ema(close, 50), e200 = A.ema(close, 200);\n    const rsiA = A.rsi(close, 14);\n    const atrA = A.atr(cs, 14);\n    const atr = last(atrA);\n    const mac = A.macd(close);\n    const bb = A.bollinger(close);\n    const st = A.stoch(cs);\n    const sup = A.supertrend(cs);\n    const adx = A.adx(cs);\n    const vwap = A.vwap(cs, tf);\n    const sw = A.swings(cs, 3);\n    const struct = A.structure(cs, sw);\n    const fvg = A.fvgs(cs, atr);\n    const ob = A.orderBlocks(cs, atrA);\n    const liq = A.liquidity(cs, sw, atr);\n    const pd = A.premiumDiscount(cs, sw);\n    const div = A.divergence(cs, rsiA, sw);\n    const fib = A.fibonacci(cs);\n    const piv = A.pivots(dailyCs && dailyCs.length > 2 ? dailyCs[dailyCs.length - 2] : cs[n - 2]);\n    const sr = A.supportResistance(sw, price, atr);\n    const candlePat = A.candlePatterns(cs, atr);\n    const chartPat = A.chartPatterns(cs, sw, atr);\n\n    const rsi = last(rsiA);\n    const volAvg = sum(cs.slice(-21, -1).map((x) => x.v)) / 20;\n    const lastC = last(cs);\n\n    /* ---- نقاط المؤشرات الـ17 (المؤشر 17 MTF يُضاف لاحقاً) ---- */\n    const I = [];\n    const add = (id, name, w, s, text, value) => I.push({ id, name, w, s: clamp(s, -1, 1), text, value });\n\n    const l9 = last(e9), l21 = last(e21), l50 = last(e50), l200 = last(e200);\n    let s1 = 0;\n    if (l9 > l21 && l21 > l50) s1 = 1; else if (l9 < l21 && l21 < l50) s1 = -1;\n    else s1 = l9 > l21 ? 0.35 : -0.35;\n    add(1, \"ترتيب EMA (9/21/50)\", 3, s1, s1 > 0.5 ? \"ترتيب صاعد\" : s1 < -0.5 ? \"ترتيب هابط\" : \"ترتيب مختلط\", `${l9.toFixed(2)} / ${l21.toFixed(2)} / ${l50.toFixed(2)}`);\n\n    add(2, \"السعر مقابل EMA 200\", 2, price > l200 ? 1 : -1, price > l200 ? \"فوق EMA200\" : \"تحت EMA200\", l200.toFixed(2));\n\n    let s3 = 0;\n    if (rsi >= 70) s3 = -0.8; else if (rsi >= 60) s3 = 0.5; else if (rsi >= 50) s3 = 0.3;\n    else if (rsi >= 40) s3 = -0.3; else if (rsi >= 30) s3 = -0.5; else s3 = 0.8;\n    add(3, \"RSI (14)\", 2, s3, rsi >= 70 ? \"تشبع شراء\" : rsi <= 30 ? \"تشبع بيع\" : rsi >= 50 ? \"زخم إيجابي\" : \"زخم سلبي\", rsi.toFixed(1));\n\n    const mL = last(mac.line), mS = last(mac.signal), mH = last(mac.hist), mH1 = last(mac.hist, 2);\n    const s4 = (mL > mS ? 0.5 : -0.5) + (mH > mH1 ? 0.3 : -0.3) + (mL > 0 ? 0.2 : -0.2);\n    add(4, \"MACD\", 2, s4, mL > mS ? \"فوق خط الإشارة\" : \"تحت خط الإشارة\", `هيستوغرام ${mH.toFixed(3)}`);\n\n    const pb = last(bb.pb);\n    let s5 = 0;\n    if (pb < 0.05) s5 = 0.8; else if (pb < 0.2) s5 = 0.4; else if (pb > 0.95) s5 = -0.8; else if (pb > 0.8) s5 = -0.4; else s5 = (pb - 0.5) * 0.4;\n    add(5, \"Bollinger %B\", 1.5, s5, pb > 0.95 ? \"عند الحد العلوي\" : pb < 0.05 ? \"عند الحد السفلي\" : \"داخل النطاق\", `%B ${(pb * 100).toFixed(0)}`);\n\n    const K = last(st.k), D = last(st.d);\n    let s6 = 0;\n    if (K < 20 && K > D) s6 = 1; else if (K < 20) s6 = 0.5; else if (K > 80 && K < D) s6 = -1; else if (K > 80) s6 = -0.5; else s6 = K > D ? 0.2 : -0.2;\n    add(6, \"Stochastic\", 1.5, s6, K < 20 ? \"تشبع بيع\" : K > 80 ? \"تشبع شراء\" : \"محايد\", `K ${K.toFixed(0)} / D ${D.toFixed(0)}`);\n\n    const stDir = last(sup.trend);\n    const flipped = sup.trend.slice(-4).some((x, i, a) => i > 0 && x !== a[i - 1]);\n    add(7, \"SuperTrend\", 2, stDir * (flipped ? 1 : 0.85), stDir > 0 ? \"اتجاه صاعد\" : \"اتجاه هابط\", (last(sup.line) || 0).toFixed(2) + (flipped ? \" (انعكاس حديث)\" : \"\"));\n\n    add(8, \"VWAP\", 1.5, price > vwap ? 0.7 : -0.7, price > vwap ? \"السعر فوق VWAP\" : \"السعر تحت VWAP\", vwap.toFixed(2));\n\n    add(9, \"هيكل السوق\", 3, struct.trend === \"bull\" ? 1 : struct.trend === \"bear\" ? -1 : 0, struct.trend === \"bull\" ? \"قمم وقيعان أعلى\" : struct.trend === \"bear\" ? \"قمم وقيعان أدنى\" : \"نطاق جانبي\", \"\");\n\n    let s10 = 0, t10 = \"لا كسر حديث\";\n    if (struct.event) {\n      const e = struct.event;\n      s10 = e.dir * (e.kind === \"CHOCH\" ? 1 : 0.8) * (e.age <= 3 ? 1 : 0.7);\n      t10 = `${e.kind} ${e.dir > 0 ? \"صاعد\" : \"هابط\"} منذ ${e.age} شمعة`;\n    }\n    add(10, \"BOS / CHOCH\", 2, s10, t10, struct.event ? struct.event.level.toFixed(2) : \"\");\n\n    let s11 = 0, t11 = \"لا فجوات قريبة\";\n    for (const g of fvg) {\n      const inside = price >= g.lo && price <= g.hi;\n      const dist = g.dir === 1 ? price - g.hi : g.lo - price;\n      if (inside || (dist >= 0 && dist <= 2 * atr)) {\n        s11 += g.dir * (inside ? 1 : 0.8);\n        t11 = inside ? \"السعر داخل FVG\" : \"FVG قريب\";\n      }\n    }\n    add(11, \"FVG قريب\", 1.5, s11, t11, \"\");\n\n    let s12 = 0, t12 = \"لا بلوك قريب\";\n    for (const o of ob) {\n      const inside = price >= o.lo && price <= o.hi;\n      const dist = o.dir === 1 ? price - o.hi : o.lo - price;\n      if (inside || (dist >= 0 && dist <= 2 * atr)) {\n        s12 += o.dir * (inside ? 1 : 0.8);\n        t12 = inside ? \"السعر داخل Order Block\" : \"Order Block قريب\";\n      }\n    }\n    add(12, \"Order Block قريب\", 1.5, s12, t12, \"\");\n\n    add(13, \"كنس السيولة\", 2.5, liq.sweep ? liq.sweep.dir * (liq.sweep.age <= 1 ? 1 : 0.7) : 0,\n      liq.sweep ? (liq.sweep.dir > 0 ? \"كنس قيعان ثم ارتداد\" : \"كنس قمم ثم رفض\") : \"لا كنس حديث\", liq.sweep ? liq.sweep.level.toFixed(2) : \"\");\n\n    add(14, \"دايفرجنس RSI\", 2.5, div ? div.dir : 0, div ? div.text : \"لا دايفرجنس\", \"\");\n\n    const dirC = lastC.c >= lastC.o ? 1 : -1;\n    const vr = volAvg ? lastC.v / volAvg : 1;\n    add(15, \"الحجم\", 1, vr > 1.5 ? dirC : vr > 1 ? dirC * 0.5 : dirC * 0.2, vr > 1.5 ? \"حجم مرتفع\" : vr > 1 ? \"حجم فوق المتوسط\" : \"حجم ضعيف\", `${vr.toFixed(2)}×`);\n\n    const ADX = last(adx.adx), PD = last(adx.pdi), MD = last(adx.mdi);\n    add(16, \"ADX قوة الاتجاه\", 1.5, ADX > 25 ? Math.sign(PD - MD) * Math.min(1, ADX / 40) : 0,\n      ADX > 25 ? (PD > MD ? \"اتجاه صاعد قوي\" : \"اتجاه هابط قوي\") : \"اتجاه ضعيف\", ADX.toFixed(1));\n\n    add(18, \"Premium / Discount\", 1.5, pd.pos < 0.3 ? 0.8 : pd.pos < 0.5 ? 0.3 : pd.pos > 0.7 ? -0.8 : -0.3,\n      pd.zone === \"discount\" ? \"منطقة خصم (رخيص)\" : \"منطقة علاوة (غالي)\", `${(pd.pos * 100).toFixed(0)}%`);\n\n    const baseW = sum(I.map((x) => x.w));\n    const baseScore = (sum(I.map((x) => x.w * x.s)) / baseW) * 100;\n\n    return {\n      tf, price, atr, candles: cs, last: lastC,\n      ind: I, baseScore,\n      raw: { rsi, adx: ADX, vwap, stochK: K, stochD: D, macd: { line: mL, signal: mS, hist: mH }, bb: { pb, up: last(bb.up), lo: last(bb.lo), mid: last(bb.mid) }, ema: { e9: l9, e21: l21, e50: l50, e200: l200 }, supertrend: { dir: stDir, line: last(sup.line) } },\n      series: { e21, e50, e200, bbUp: bb.up, bbLo: bb.lo },\n      structure: struct, swings: sw, fvg, ob, liquidity: liq, pd, divergence: div, fib, pivots: piv, sr,\n      candlePatterns: candlePat, chartPatterns: chartPat,\n    };\n  };\n\n  /* ================= دمج الأطر + المحرك النهائي ================= */\n  A.signalLabel = (s) => {\n    if (s >= 45) return { text: \"شراء قوي\", cls: \"sbuy2\", dir: 1 };\n    if (s >= 20) return { text: \"شراء\", cls: \"sbuy\", dir: 1 };\n    if (s >= 10) return { text: \"ميل صاعد\", cls: \"lbuy\", dir: 0 };\n    if (s <= -45) return { text: \"بيع قوي\", cls: \"ssell2\", dir: -1 };\n    if (s <= -20) return { text: \"بيع\", cls: \"ssell\", dir: -1 };\n    if (s <= -10) return { text: \"ميل هابط\", cls: \"lsell\", dir: 0 };\n    return { text: \"محايد\", cls: \"neutral\", dir: 0 };\n  };\n\n  A.confluence = (main, mtfMap) => {\n    const tfs = Object.keys(mtfMap);\n    const scores = tfs.map((k) => mtfMap[k].baseScore);\n    const avg = sum(scores) / scores.length;\n    const aligned = scores.filter((s) => Math.sign(s) === Math.sign(avg) && Math.abs(s) >= 10).length;\n    const s17 = clamp(avg / 50, -1, 1) * (aligned === scores.length ? 1 : 0.7);\n    const mtfInd = {\n      id: 17, name: \"توافق الأطر الزمنية\", w: 3, s: s17,\n      text: aligned === scores.length ? \"كل الأطر متفقة\" : `${aligned}/${scores.length} أطر متفقة`,\n      value: tfs.map((k) => `${k}:${mtfMap[k].baseScore.toFixed(0)}`).join(\" \"),\n    };\n    const ind = [...main.ind, mtfInd].sort((a, b) => a.id - b.id);\n    const W = sum(ind.map((x) => x.w));\n    const score = (sum(ind.map((x) => x.w * x.s)) / W) * 100;\n    const dirSign = Math.sign(score);\n    const active = ind.filter((x) => Math.abs(x.s) >= 0.15);\n    const agreeW = sum(active.filter((x) => Math.sign(x.s) === dirSign).map((x) => x.w));\n    const actW = sum(active.map((x) => x.w)) || 1;\n    const agree = agreeW / actW;\n    const conf = Math.round(clamp(30 + Math.abs(score) * 0.55 + (agree - 0.5) * 50 + (aligned === scores.length ? 8 : 0), 5, 95));\n    const label = A.signalLabel(score);\n    return {\n      score, label, confidence: conf, agree, ind, aligned, total: scores.length,\n      bull: ind.filter((x) => x.s >= 0.15).length, bear: ind.filter((x) => x.s <= -0.15).length,\n      mtf: tfs.map((k) => ({ tf: k, score: mtfMap[k].baseScore, label: A.signalLabel(mtfMap[k].baseScore), price: mtfMap[k].price })),\n    };\n  };\n\n  A.tradePlan = (main, conf) => {\n    const price = main.price, atr = main.atr;\n    const dir = conf.score >= 10 ? 1 : conf.score <= -10 ? -1 : 0;\n    if (!dir) return { dir: 0 };\n    const strong = Math.abs(conf.score) >= 20;\n    // وقف الخسارة: الأقصى بين 1.5 ATR وهيكل السوق (بحد 3 ATR)\n    let slDist = 1.5 * atr;\n    const struct = dir === 1 ? main.structure.lastL : main.structure.lastH;\n    if (struct) {\n      const d = Math.abs(price - struct.p) + 0.2 * atr;\n      if (d > slDist && d <= 3 * atr) slDist = d;\n    }\n    const entry = price;\n    const sl = entry - dir * slDist;\n    const tp = [2, 3.5, 5].map((m) => entry + dir * m * atr);\n    const rr = tp.map((t) => Math.abs(t - entry) / slDist);\n    // دخول بديل (ارتداد) من أقرب OB/FVG بنفس الاتجاه\n    const zones = [...main.ob, ...main.fvg].filter((z) => z.dir === dir && (dir === 1 ? z.hi < price : z.lo > price));\n    zones.sort((a, b) => (dir === 1 ? b.hi - a.hi : a.lo - b.lo));\n    const z = zones[0];\n    const limit = z ? (dir === 1 ? z.hi : z.lo) : null;\n    const limitSL = limit != null ? limit - dir * Math.max(1.2 * atr, 0) : null;\n    return { dir, strong, entry, sl, slDist, tp, rr, limit, limitSL, atr };\n  };\n\n  root.Analysis = A;\n  if (typeof module !== \"undefined\") module.exports = A;\n})(typeof window !== \"undefined\" ? window : globalThis);\n\n</script>\n<script>\n(function () {\n  const A = window.Analysis;\n  const SYMS = [\n    { id: \"PAXGUSDT\", name: \"الذهب\", short: \"XAU\" },\n    { id: \"BTCUSDT\", name: \"بيتكوين\", short: \"BTC\" },\n    { id: \"ETHUSDT\", name: \"إيثيريوم\", short: \"ETH\" },\n  ];\n  const TFS = [\n    { id: \"15m\", name: \"15د\" },\n    { id: \"1h\", name: \"ساعة\" },\n    { id: \"4h\", name: \"4س\" },\n    { id: \"1d\", name: \"يومي\" },\n  ];\n  const TABS = [\n    { id: \"signal\", name: \"🎯 إشارة\" },\n    { id: \"smc\", name: \"🏗️ SMC\" },\n    { id: \"ind\", name: \"📈 مؤشرات\" },\n    { id: \"pat\", name: \"🕯️ أنماط\" },\n    { id: \"risk\", name: \"🛡️ مخاطر\" },\n  ];\n\n  const st = { sym: \"PAXGUSDT\", tf: \"1h\", tab: \"signal\", data: null, err: null, loading: false, risk: { cap: 1000, riskPct: 1, lev: 1 } };\n  const $ = (s) => document.querySelector(s);\n  const view = $(\"#view\");\n\n  const fmt = (p) => (p == null || !isFinite(p) ? \"—\" : p >= 1000 ? p.toLocaleString(\"en-US\", { maximumFractionDigits: 2, minimumFractionDigits: 2 }) : p >= 10 ? p.toFixed(2) : p.toFixed(4));\n  const cls = (d) => (d > 0 ? \"up\" : d < 0 ? \"dn\" : \"mut\");\n  const arrow = (d) => (d > 0 ? \"▲\" : d < 0 ? \"▼\" : \"◆\");\n  const L = (s) => `<span class=\"ltr\">${s}</span>`;\n  const tfName = (k) => (TFS.find((t) => t.id === k) || {}).name || k;\n\n  /* ---------- جلب البيانات ---------- */\n  async function fetchTf(sym, tf) {\n    const r = await fetch(`/api/klines?symbol=${sym}&interval=${tf}&limit=500`);\n    const j = await r.json();\n    if (!r.ok) throw new Error(j.error || \"خطأ في جلب البيانات\");\n    // الشمعة الأخيرة قد تكون غير مكتملة؛ نبقيها (تحليل لحظي)\n    return j;\n  }\n\n  async function load() {\n    if (st.loading) return;\n    st.loading = true; st.err = null;\n    if (!st.data) view.innerHTML = '<div class=\"loading\">جارٍ تحميل البيانات…</div>';\n    try {\n      const res = await Promise.all([\"15m\", \"1h\", \"4h\", \"1d\"].map((tf) => fetchTf(st.sym, tf)));\n      const by = {};\n      [\"15m\", \"1h\", \"4h\", \"1d\"].forEach((tf, i) => (by[tf] = res[i]));\n      const daily = by[\"1d\"].candles;\n      const mtf = {};\n      [\"15m\", \"1h\", \"4h\"].forEach((tf) => (mtf[tf] = A.analyze(by[tf].candles, tf, daily)));\n      // الإطار اليومي كتحليل مستقل أيضاً عند اختياره\n      const all = { ...mtf };\n      if (st.tf === \"1d\") all[\"1d\"] = A.analyze(daily, \"1d\", daily);\n      st.data = { all, mtf, daily, source: by[\"1h\"].source, ts: Date.now() };\n    } catch (e) {\n      st.err = e.message || String(e);\n    }\n    st.loading = false;\n    render();\n  }\n\n  /* ---------- بناء النتيجة للإطار المختار ---------- */\n  function result() {\n    const d = st.data;\n    if (!d) return null;\n    let main = d.all[st.tf];\n    if (!main) main = A.analyze(d.daily, \"1d\", d.daily);\n    const conf = A.confluence(main, d.mtf);\n    const plan = A.tradePlan(main, conf);\n    return { main, conf, plan };\n  }\n\n  /* ---------- الرسم ---------- */\n  function drawChart(main, plan) {\n    const cv = $(\"#chart\");\n    if (!cv) return;\n    const dpr = window.devicePixelRatio || 1;\n    const W = cv.clientWidth, H = cv.clientHeight;\n    cv.width = W * dpr; cv.height = H * dpr;\n    const g = cv.getContext(\"2d\");\n    g.scale(dpr, dpr);\n    const N = Math.min(90, main.candles.length);\n    const off = main.candles.length - N;\n    const cs = main.candles.slice(-N);\n    const padR = 64, padT = 10, padB = 18;\n    let hi = Math.max(...cs.map((c) => c.h)), lo = Math.min(...cs.map((c) => c.l));\n    if (plan && plan.dir) {\n      hi = Math.max(hi, plan.tp[0], plan.entry); lo = Math.min(lo, plan.sl, plan.entry);\n      if (plan.dir < 0) lo = Math.min(lo, plan.tp[0]);\n    }\n    const rg = (hi - lo) || 1; hi += rg * 0.04; lo -= rg * 0.04;\n    const X = (i) => 6 + (i + 0.5) * ((W - padR - 6) / N);\n    const Y = (p) => padT + ((hi - p) / (hi - lo)) * (H - padT - padB);\n    const cw = Math.max(2, ((W - padR - 6) / N) * 0.62);\n\n    g.fillStyle = \"#0e1420\"; g.fillRect(0, 0, W, H);\n    g.strokeStyle = \"#1c2638\"; g.lineWidth = 1; g.fillStyle = \"#6b7a93\"; g.font = \"10px system-ui\"; g.textAlign = \"left\";\n    for (let k = 0; k <= 5; k++) {\n      const p = lo + ((hi - lo) * k) / 5, y = Y(p);\n      g.beginPath(); g.moveTo(0, y); g.lineTo(W - padR, y); g.stroke();\n      g.fillText(fmt(p), W - padR + 4, y + 3);\n    }\n    // مناطق FVG / OB\n    const zone = (z, color, label) => {\n      const x0 = Math.max(6, X(Math.max(0, z.i - off)));\n      g.fillStyle = color;\n      g.fillRect(x0, Y(z.hi), W - padR - x0, Math.max(2, Y(z.lo) - Y(z.hi)));\n      g.fillStyle = \"#cbd5e1\"; g.font = \"9px system-ui\"; g.textAlign = \"left\";\n      g.fillText(label, x0 + 2, Y(z.hi) + 9);\n    };\n    main.fvg.forEach((z) => zone(z, z.dir > 0 ? \"rgba(34,197,94,.16)\" : \"rgba(239,68,68,.16)\", \"FVG\"));\n    main.ob.forEach((z) => zone(z, z.dir > 0 ? \"rgba(76,154,255,.22)\" : \"rgba(245,158,11,.22)\", \"OB\"));\n    // EMA\n    const line = (arr, color) => {\n      g.strokeStyle = color; g.lineWidth = 1.2; g.beginPath();\n      let s = false;\n      cs.forEach((_, i) => { const v = arr[off + i]; if (v == null) return; const x = X(i), y = Y(v); s ? g.lineTo(x, y) : (g.moveTo(x, y), (s = true)); });\n      g.stroke();\n    };\n    line(main.series.e21, \"#4c9aff\"); line(main.series.e50, \"#f5b942\"); line(main.series.e200, \"#a78bfa\");\n    // الشموع\n    cs.forEach((c, i) => {\n      const x = X(i), up = c.c >= c.o, col = up ? \"#22c55e\" : \"#ef4444\";\n      g.strokeStyle = col; g.fillStyle = col; g.lineWidth = 1;\n      g.beginPath(); g.moveTo(x, Y(c.h)); g.lineTo(x, Y(c.l)); g.stroke();\n      const y1 = Y(Math.max(c.o, c.c)), y2 = Y(Math.min(c.o, c.c));\n      g.fillRect(x - cw / 2, y1, cw, Math.max(1, y2 - y1));\n    });\n    // مستويات الصفقة\n    const hl = (p, color, label) => {\n      g.strokeStyle = color; g.setLineDash([5, 4]); g.lineWidth = 1.2;\n      g.beginPath(); g.moveTo(0, Y(p)); g.lineTo(W - padR, Y(p)); g.stroke(); g.setLineDash([]);\n      g.fillStyle = color; g.font = \"bold 10px system-ui\"; g.textAlign = \"left\";\n      g.fillText(label + \" \" + fmt(p), W - padR + 4, Y(p) - 2);\n    };\n    if (plan && plan.dir) { hl(plan.entry, \"#e6edf7\", \"دخول\"); hl(plan.sl, \"#ef4444\", \"SL\"); plan.tp.slice(0, 2).forEach((t, i) => hl(t, \"#22c55e\", \"TP\" + (i + 1))); }\n    g.fillStyle = \"#6b7a93\"; g.font = \"10px system-ui\"; g.textAlign = \"left\";\n    g.fillText(\"EMA21 أزرق · EMA50 ذهبي · EMA200 بنفسجي\", 8, H - 5);\n  }\n\n  /* ---------- التبويبات ---------- */\n  function tabSignal(r) {\n    const { main, conf, plan } = r;\n    const pos = (conf.score + 100) / 2;\n    const lab = conf.label;\n    const decision = plan.dir\n      ? `<div class=\"kv\"><span>الاتجاه</span><b class=\"${cls(plan.dir)}\">${plan.dir > 0 ? \"شراء (Long) ▲\" : \"بيع (Short) ▼\"}</b></div>\n         <div class=\"kv\"><span>نقطة الدخول (السوق)</span><b>${L(fmt(plan.entry))}</b></div>\n         ${plan.limit != null ? `<div class=\"kv\"><span>دخول بديل عند الارتداد (منطقة OB/FVG)</span><b>${L(fmt(plan.limit))}</b></div>` : \"\"}\n         <div class=\"kv\"><span>وقف الخسارة</span><b class=\"dn\">${L(fmt(plan.sl))} <span class=\"pill\">${L(fmt(plan.slDist))}</span></b></div>\n         ${plan.tp.map((t, i) => `<div class=\"kv\"><span>الهدف ${i + 1} <span class=\"pill\">ATR×${[2, 3.5, 5][i]}</span></span><b class=\"up\">${L(fmt(t))} <span class=\"pill\">R:R ${plan.rr[i].toFixed(2)}</span></b></div>`).join(\"\")}\n         ${!plan.strong ? '<div class=\"warn\" style=\"font-size:12px;margin-top:8px\">⚠ الإشارة ضعيفة (ميل فقط) — الأفضل الانتظار لتأكيد أو تلاقٍ أقوى.</div>' : \"\"}`\n      : '<div class=\"mut\">لا توجد صفقة واضحة — السوق محايد. الأفضل الانتظار.</div>';\n\n    return `\n    <div class=\"card hero\">\n      <div class=\"mut\" style=\"font-size:13px\">محرك التلاقي — 18 مؤشراً · الإطار ${tfName(main.tf)}</div>\n      <div class=\"big\"><span class=\"tag ${lab.cls}\" style=\"font-size:22px;padding:6px 22px\">${lab.text}</span></div>\n      <div style=\"font-size:14px\">الدرجة <b class=\"ltr\">${conf.score.toFixed(1)}</b> / 100 · الثقة <b>${conf.confidence}%</b></div>\n      <div class=\"gauge\"><i style=\"left:${pos}%\"></i></div>\n      <div class=\"glab\"><span>بيع قوي</span><span>محايد</span><span>شراء قوي</span></div>\n      <div class=\"mut\" style=\"font-size:12px;margin-top:10px\">🟢 ${conf.bull} مؤشر صاعد · 🔴 ${conf.bear} مؤشر هابط · اتفاق موزون ${(conf.agree * 100).toFixed(0)}%</div>\n    </div>\n    <div class=\"card\"><h3>الرسم البياني + المناطق</h3><canvas id=\"chart\"></canvas></div>\n    <div class=\"grid\">\n      <div class=\"card\"><h3>⏱️ تحليل متعدد الأطر (MTF)</h3>\n        ${conf.mtf.map((m) => `<div class=\"kv\"><span>${tfName(m.tf)}</span><span><span class=\"tag ${m.label.cls}\">${m.label.text}</span> <span class=\"ltr mut\">${m.score.toFixed(0)}</span></span></div>`).join(\"\")}\n        <div class=\"mut\" style=\"font-size:12px;margin-top:8px\">${conf.aligned === conf.total ? \"✅ كل الأطر متفقة = إشارة أقوى\" : `${conf.aligned}/${conf.total} أطر متفقة`}</div>\n      </div>\n      <div class=\"card\"><h3>🎯 خطة التداول</h3>${decision}</div>\n    </div>`;\n  }\n\n  function zoneRows(arr, label) {\n    if (!arr.length) return `<div class=\"mut\">لا يوجد</div>`;\n    return arr.slice().reverse().map((z) => `<div class=\"kv\"><span class=\"${cls(z.dir)}\">${label} ${z.dir > 0 ? \"صاعد\" : \"هابط\"}</span><b>${L(fmt(z.lo))} – ${L(fmt(z.hi))}</b></div>`).join(\"\");\n  }\n\n  function tabSMC(r) {\n    const m = r.main, s = m.structure;\n    const trend = s.trend === \"bull\" ? [\"صاعد (HH/HL)\", 1] : s.trend === \"bear\" ? [\"هابط (LH/LL)\", -1] : [\"نطاق جانبي\", 0];\n    const ev = s.event ? `${s.event.kind} ${s.event.dir > 0 ? \"صاعد\" : \"هابط\"} عند ${fmt(s.event.level)} (منذ ${s.event.age} شمعة)` : \"لا كسر حديث\";\n    const liq = m.liquidity;\n    return `<div class=\"grid\">\n      <div class=\"card\"><h3>🏗️ هيكل السوق</h3>\n        <div class=\"kv\"><span>الاتجاه</span><b class=\"${cls(trend[1])}\">${trend[0]}</b></div>\n        <div class=\"kv\"><span>آخر قمة متأرجحة</span><b>${s.lastH ? L(fmt(s.lastH.p)) : \"—\"}</b></div>\n        <div class=\"kv\"><span>آخر قاع متأرجح</span><b>${s.lastL ? L(fmt(s.lastL.p)) : \"—\"}</b></div>\n        <div class=\"kv\"><span>BOS / CHOCH</span><b class=\"${cls(s.event ? s.event.dir : 0)}\">${ev}</b></div>\n      </div>\n      <div class=\"card\"><h3>📊 Premium / Discount</h3>\n        <div class=\"kv\"><span>أعلى المدى</span><b>${L(fmt(m.pd.hi))}</b></div>\n        <div class=\"kv\"><span>التوازن (50%)</span><b>${L(fmt(m.pd.eq))}</b></div>\n        <div class=\"kv\"><span>أدنى المدى</span><b>${L(fmt(m.pd.lo))}</b></div>\n        <div class=\"kv\"><span>موقع السعر</span><b class=\"${m.pd.zone === \"discount\" ? \"up\" : \"dn\"}\">${(m.pd.pos * 100).toFixed(0)}% — ${m.pd.zone === \"discount\" ? \"خصم (مفضّل للشراء)\" : \"علاوة (مفضّل للبيع)\"}</b></div>\n        <div class=\"bar\"><span style=\"left:0;right:${100 - m.pd.pos * 100}%;background:${m.pd.zone === \"discount\" ? \"var(--up)\" : \"var(--dn)\"}\"></span></div>\n      </div>\n      <div class=\"card\"><h3>⚡ فجوات القيمة العادلة (FVG نشطة)</h3>${zoneRows(m.fvg, \"FVG\")}</div>\n      <div class=\"card\"><h3>📦 بلوكات الأوامر (غير مخففة)</h3>${zoneRows(m.ob, \"OB\")}</div>\n      <div class=\"card\"><h3>💧 السيولة</h3>\n        <div class=\"kv\"><span>قمم متساوية (Buy-side)</span><b>${liq.eqh.length ? liq.eqh.map((x) => L(fmt(x.level))).join(\" · \") : \"—\"}</b></div>\n        <div class=\"kv\"><span>قيعان متساوية (Sell-side)</span><b>${liq.eql.length ? liq.eql.map((x) => L(fmt(x.level))).join(\" · \") : \"—\"}</b></div>\n        <div class=\"kv\"><span>كنس حديث</span><b class=\"${cls(liq.sweep ? liq.sweep.dir : 0)}\">${liq.sweep ? (liq.sweep.dir > 0 ? \"كنس قيعان → ارتداد\" : \"كنس قمم → رفض\") + ` عند ${fmt(liq.sweep.level)}` : \"لا يوجد\"}</b></div>\n      </div>\n      <div class=\"card\"><h3>📐 فيبوناتشي (${m.fib.dir > 0 ? \"موجة صاعدة\" : \"موجة هابطة\"})</h3>\n        ${m.fib.levels.map((x) => `<div class=\"kv\"><span>${x.f}</span><b>${L(fmt(x.p))}</b></div>`).join(\"\")}\n        ${m.fib.ext.map((x) => `<div class=\"kv\"><span>امتداد ${x.f}</span><b class=\"mut\">${L(fmt(x.p))}</b></div>`).join(\"\")}\n      </div>\n      <div class=\"card\"><h3>📍 نقاط البيفوت (يومي)</h3>\n        ${[\"R3\", \"R2\", \"R1\", \"P\", \"S1\", \"S2\", \"S3\"].map((k) => `<div class=\"kv\"><span class=\"${k[0] === \"R\" ? \"dn\" : k[0] === \"S\" ? \"up\" : \"\"}\">${k}</span><b>${L(fmt(m.pivots[k]))}</b></div>`).join(\"\")}\n      </div>\n    </div>`;\n  }\n\n  function heatColor(s) {\n    const a = Math.min(1, Math.abs(s));\n    return s > 0.1 ? `rgba(34,197,94,${0.18 + a * 0.55})` : s < -0.1 ? `rgba(239,68,68,${0.18 + a * 0.55})` : \"rgba(100,116,139,.25)\";\n  }\n\n  function tabInd(r) {\n    const { main, conf } = r, rw = main.raw;\n    return `\n    <div class=\"card\"><h3>🔥 خريطة الحرارة (18 مؤشر)</h3>\n      <div class=\"heat\">${conf.ind.map((x) => `<div style=\"background:${heatColor(x.s)}\"><b>${x.id}. ${x.name}</b>${x.s > 0.1 ? \"صاعد\" : x.s < -0.1 ? \"هابط\" : \"محايد\"}</div>`).join(\"\")}</div>\n    </div>\n    <div class=\"card\"><h3>تفاصيل المؤشرات (الوزن × الدرجة)</h3>\n      <table><tr><th>#</th><th>المؤشر</th><th>الحالة</th><th>القيمة</th><th>وزن</th><th>درجة</th></tr>\n      ${conf.ind.map((x) => `<tr><td>${x.id}</td><td>${x.name}</td><td>${x.text}</td><td>${L(x.value)}</td><td>${x.w}</td><td class=\"${cls(x.s)}\">${L((x.s > 0 ? \"+\" : \"\") + x.s.toFixed(2))}</td></tr>`).join(\"\")}\n      </table>\n    </div>\n    <div class=\"grid\">\n      <div class=\"card\"><h3>قراءات خام</h3>\n        <div class=\"kv\"><span>RSI</span><b>${rw.rsi.toFixed(1)}</b></div>\n        <div class=\"kv\"><span>ADX</span><b>${rw.adx.toFixed(1)}</b></div>\n        <div class=\"kv\"><span>ATR (14)</span><b>${L(fmt(main.atr))}</b></div>\n        <div class=\"kv\"><span>VWAP</span><b>${L(fmt(rw.vwap))}</b></div>\n        <div class=\"kv\"><span>Bollinger</span><b>${L(fmt(rw.bb.lo))} – ${L(fmt(rw.bb.up))}</b></div>\n        <div class=\"kv\"><span>SuperTrend</span><b class=\"${cls(rw.supertrend.dir)}\">${L(fmt(rw.supertrend.line))}</b></div>\n      </div>\n      <div class=\"card\"><h3>المتوسطات</h3>\n        ${[\"e9\", \"e21\", \"e50\", \"e200\"].map((k) => `<div class=\"kv\"><span>EMA ${k.slice(1)}</span><b class=\"${cls(main.price - rw.ema[k])}\">${L(fmt(rw.ema[k]))}</b></div>`).join(\"\")}\n      </div>\n    </div>`;\n  }\n\n  function tabPat(r) {\n    const m = r.main;\n    const row = (p) => `<div class=\"kv\"><span class=\"${cls(p.dir)}\">${p.name}</span><b>${p.status ? p.status + \" · \" : \"\"}${p.level ? L(fmt(p.level)) : p.age === 0 ? \"الشمعة الحالية\" : `منذ ${p.age} شمعة`}</b></div>`;\n    return `<div class=\"grid\">\n      <div class=\"card\"><h3>🕯️ أنماط الشموع (آخر 3 شموع)</h3>${m.candlePatterns.length ? m.candlePatterns.map(row).join(\"\") : '<div class=\"mut\">لا نمط واضح</div>'}</div>\n      <div class=\"card\"><h3>📐 أنماط الرسم البياني</h3>${m.chartPatterns.length ? m.chartPatterns.map(row).join(\"\") : '<div class=\"mut\">لا نمط مكتمل التشكل حالياً</div>'}</div>\n      <div class=\"card\"><h3>🔴 مقاومة</h3>${m.sr.resistance.length ? m.sr.resistance.map((x) => `<div class=\"kv\"><span>${x.n} لمسات</span><b class=\"dn\">${L(fmt(x.p))}</b></div>`).join(\"\") : '<div class=\"mut\">—</div>'}</div>\n      <div class=\"card\"><h3>🟢 دعم</h3>${m.sr.support.length ? m.sr.support.map((x) => `<div class=\"kv\"><span>${x.n} لمسات</span><b class=\"up\">${L(fmt(x.p))}</b></div>`).join(\"\") : '<div class=\"mut\">—</div>'}</div>\n      <div class=\"card\"><h3>دايفرجنس</h3>${m.divergence ? `<b class=\"${cls(m.divergence.dir)}\">${m.divergence.text}</b>` : '<div class=\"mut\">لا يوجد دايفرجنس حالياً</div>'}</div>\n    </div>`;\n  }\n\n  function killzones() {\n    const zones = [\n      { n: \"آسيا\", s: 0, e: 5, d: \"تكوين النطاق — سيولة منخفضة\" },\n      { n: \"لندن\", s: 7, e: 10, d: \"أقوى جلسة للحركات الاتجاهية وكنس السيولة\" },\n      { n: \"نيويورك\", s: 12, e: 15, d: \"أعلى تذبذب — أخبار أمريكية\" },\n      { n: \"إغلاق لندن\", s: 15, e: 17, d: \"تصحيحات وانعكاسات\" },\n    ];\n    const now = new Date(), h = now.getUTCHours() + now.getUTCMinutes() / 60;\n    const loc = (u) => { const d = new Date(); d.setUTCHours(u, 0, 0, 0); return d.toLocaleTimeString(\"ar\", { hour: \"2-digit\", minute: \"2-digit\", hour12: false }); };\n    return zones.map((z) => { const on = h >= z.s && h < z.e; return `<div class=\"kz ${on ? \"on\" : \"\"}\"><span><b>${z.n}</b> ${on ? \"🟢 نشطة الآن\" : \"\"}<div class=\"mut\" style=\"font-size:12px\">${z.d}</div></span><span class=\"ltr\">${loc(z.s)} – ${loc(z.e)}</span></div>`; }).join(\"\") +\n      '<div class=\"mut\" style=\"font-size:11px;margin-top:6px\">الأوقات بتوقيت جهازك (مبنية على توقيت نيويورك الشتوي؛ تتأخر ساعة صيفاً).</div>';\n  }\n\n  function tabRisk(r) {\n    const { plan, main } = r;\n    const c = st.risk;\n    const entry = plan.dir ? plan.entry : main.price;\n    const sl = plan.dir ? plan.sl : main.price - 1.5 * main.atr;\n    const dir = plan.dir || 1;\n    const riskAmt = (c.cap * c.riskPct) / 100;\n    const dist = Math.abs(entry - sl);\n    const size = dist ? riskAmt / dist : 0;\n    const val = size * entry;\n    const tps = plan.dir ? plan.tp : [2, 3.5, 5].map((m) => entry + dir * m * main.atr);\n    const margin = c.lev > 0 ? val / c.lev : val;\n    return `<div class=\"grid\">\n      <div class=\"card\"><h3>🧮 حاسبة إدارة المخاطر</h3>\n        <div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px\">\n          <div><label>رأس المال ($)</label><input id=\"rCap\" type=\"number\" inputmode=\"decimal\" value=\"${c.cap}\"></div>\n          <div><label>المخاطرة %</label><input id=\"rPct\" type=\"number\" inputmode=\"decimal\" step=\"0.25\" value=\"${c.riskPct}\"></div>\n          <div><label>الرافعة ×</label><input id=\"rLev\" type=\"number\" inputmode=\"decimal\" value=\"${c.lev}\"></div>\n        </div>\n        <div style=\"margin-top:12px\">\n          <div class=\"kv\"><span>المبلغ المعرّض للخسارة</span><b class=\"dn\">$${riskAmt.toFixed(2)}</b></div>\n          <div class=\"kv\"><span>الدخول / الوقف</span><b>${L(fmt(entry))} / ${L(fmt(sl))}</b></div>\n          <div class=\"kv\"><span>حجم الصفقة (${SYMS.find((s) => s.id === st.sym).short})</span><b>${L(size >= 1 ? size.toFixed(3) : size.toFixed(6))}</b></div>\n          <div class=\"kv\"><span>قيمة المركز</span><b>$${val.toFixed(2)}</b></div>\n          <div class=\"kv\"><span>الهامش المطلوب</span><b class=\"${margin > c.cap ? \"dn\" : \"\"}\">$${margin.toFixed(2)} ${margin > c.cap ? \"⚠ يتجاوز رأس المال\" : \"\"}</b></div>\n          ${tps.map((t, i) => { const pr = Math.abs(t - entry) * size; return `<div class=\"kv\"><span>ربح عند الهدف ${i + 1} (${L(fmt(t))})</span><b class=\"up\">+$${pr.toFixed(2)} <span class=\"pill\">R:R ${(Math.abs(t - entry) / (dist || 1)).toFixed(2)}</span></b></div>`; }).join(\"\")}\n        </div>\n        ${plan.dir ? \"\" : '<div class=\"warn\" style=\"font-size:12px;margin-top:8px\">لا توجد إشارة واضحة؛ الأرقام مبنية على سيناريو شراء افتراضي.</div>'}\n        <div class=\"mut\" style=\"font-size:12px;margin-top:8px\">قاعدة عامة: لا تخاطر بأكثر من 1–2% من رأس المال في الصفقة الواحدة.</div>\n      </div>\n      <div class=\"card\"><h3>⏰ مناطق القتل (Killzones)</h3>${killzones()}</div>\n    </div>`;\n  }\n\n  /* ---------- العرض ---------- */\n  function render() {\n    // الأزرار\n    $(\"#symSeg\").innerHTML = SYMS.map((s) => `<button class=\"${s.id === st.sym ? \"on\" : \"\"}\" data-sym=\"${s.id}\">${s.name}</button>`).join(\"\");\n    $(\"#tfSeg\").innerHTML = TFS.map((t) => `<button class=\"${t.id === st.tf ? \"on\" : \"\"}\" data-tf=\"${t.id}\">${t.name}</button>`).join(\"\");\n    $(\"#tabs\").innerHTML = TABS.map((t) => `<button class=\"${t.id === st.tab ? \"on\" : \"\"}\" data-tab=\"${t.id}\">${t.name}</button>`).join(\"\");\n\n    if (st.err && !st.data) { view.innerHTML = `<div class=\"err\">⚠️ ${st.err}<br><button class=\"iconbtn\" style=\"margin-top:8px\" id=\"retry\">إعادة المحاولة</button></div>`; const b = $(\"#retry\"); if (b) b.onclick = load; return; }\n    if (!st.data) return;\n\n    const r = result();\n    const d = st.data;\n    const day = d.daily;\n    const ref = day[day.length - 2] ? day[day.length - 2].c : r.main.candles[0].c; // إغلاق أمس\n    const pct = ((r.main.price - ref) / ref) * 100;\n    $(\"#price\").textContent = fmt(r.main.price);\n    $(\"#chg\").innerHTML = `<span class=\"${cls(pct)}\">${arrow(pct)} ${pct.toFixed(2)}% (يومي)</span>`;\n    $(\"#meta\").textContent = `المصدر: ${d.source} · آخر تحديث ${new Date(d.ts).toLocaleTimeString(\"ar\", { hour12: false })}${st.err ? \" · ⚠ تعذر التحديث الأخير\" : \"\"}`;\n\n    const body = { signal: tabSignal, smc: tabSMC, ind: tabInd, pat: tabPat, risk: tabRisk }[st.tab](r);\n    view.innerHTML = body;\n    if (st.tab === \"signal\") drawChart(r.main, r.plan);\n    if (st.tab === \"risk\") {\n      const bind = (id, k) => { const el = $(id); el.onchange = () => { st.risk[k] = Math.max(0, parseFloat(el.value) || 0); render(); }; };\n      bind(\"#rCap\", \"cap\"); bind(\"#rPct\", \"riskPct\"); bind(\"#rLev\", \"lev\");\n    }\n  }\n\n  document.addEventListener(\"click\", (e) => {\n    const b = e.target.closest(\"button\");\n    if (!b) return;\n    if (b.dataset.sym) { st.sym = b.dataset.sym; st.data = null; load(); render(); }\n    else if (b.dataset.tf) { const prev = st.tf; st.tf = b.dataset.tf; if (st.tf === \"1d\" && st.data && !st.data.all[\"1d\"]) st.data.all[\"1d\"] = A.analyze(st.data.daily, \"1d\", st.data.daily); render(); }\n    else if (b.dataset.tab) { st.tab = b.dataset.tab; render(); window.scrollTo({ top: 0 }); }\n    else if (b.id === \"refresh\") load();\n  });\n  window.addEventListener(\"resize\", () => { const r = st.data && result(); if (r && st.tab === \"signal\") drawChart(r.main, r.plan); });\n\n  render();\n  load();\n  setInterval(load, 60000);\n})();\n\n</script>\n</body>\n</html>\n";

const SYMBOLS = {
  BTCUSDT: { kraken: "XBTUSD" },
  PAXGUSDT: { kraken: "PAXGUSD" }, // PAX Gold = أونصة ذهب
  ETHUSDT: { kraken: "ETHUSD" },
};
const INTERVALS = {
  "15m": { binance: "15m", bybit: "15", kraken: 15 },
  "1h": { binance: "1h", bybit: "60", kraken: 60 },
  "4h": { binance: "4h", bybit: "240", kraken: 240 },
  "1d": { binance: "1d", bybit: "D", kraken: 1440 },
};

const json = (data, status = 200, extra = {}) =>
  new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "access-control-allow-origin": "*", ...extra },
  });

async function getJSON(url) {
  const r = await fetch(url, { headers: { "user-agent": "gold-btc-analyzer/1.0", accept: "application/json" } });
  if (!r.ok) throw new Error(`${new URL(url).host} -> ${r.status}`);
  return r.json();
}

const num = (x) => parseFloat(x);

const sources = {
  async binance(sym, iv, limit) {
    return (await getJSON(`https://api.binance.com/api/v3/klines?symbol=${sym}&interval=${iv.binance}&limit=${limit}`)).map(
      (k) => ({ t: k[0], o: num(k[1]), h: num(k[2]), l: num(k[3]), c: num(k[4]), v: num(k[5]) })
    );
  },
  async binanceVision(sym, iv, limit) {
    return (await getJSON(`https://data-api.binance.vision/api/v3/klines?symbol=${sym}&interval=${iv.binance}&limit=${limit}`)).map(
      (k) => ({ t: k[0], o: num(k[1]), h: num(k[2]), l: num(k[3]), c: num(k[4]), v: num(k[5]) })
    );
  },
  async bybit(sym, iv, limit) {
    const d = await getJSON(`https://api.bybit.com/v5/market/kline?category=spot&symbol=${sym}&interval=${iv.bybit}&limit=${limit}`);
    if (d.retCode !== 0 || !d.result?.list?.length) throw new Error("bybit empty");
    return d.result.list.map((k) => ({ t: num(k[0]), o: num(k[1]), h: num(k[2]), l: num(k[3]), c: num(k[4]), v: num(k[5]) })).reverse();
  },
  async kraken(sym, iv, limit) {
    const pair = SYMBOLS[sym].kraken;
    const d = await getJSON(`https://api.kraken.com/0/public/OHLC?pair=${pair}&interval=${iv.kraken}`);
    if (d.error?.length) throw new Error("kraken " + d.error[0]);
    const key = Object.keys(d.result).find((k) => k !== "last");
    return d.result[key].map((k) => ({ t: k[0] * 1000, o: num(k[1]), h: num(k[2]), l: num(k[3]), c: num(k[4]), v: num(k[6]) })).slice(-limit);
  },
};

async function klines(sym, ivKey, limit) {
  const iv = INTERVALS[ivKey];
  const errors = [];
  for (const name of ["binance", "binanceVision", "bybit", "kraken"]) {
    try {
      const data = await sources[name](sym, iv, limit);
      if (data.length >= 60) return { source: name, candles: data };
      errors.push(`${name}: قليل`);
    } catch (e) {
      errors.push(String(e.message || e));
    }
  }
  throw new Error("تعذر جلب البيانات: " + errors.join(" | "));
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (request.method === "OPTIONS")
      return new Response(null, { headers: { "access-control-allow-origin": "*", "access-control-allow-methods": "GET", "access-control-allow-headers": "*" } });

    if (url.pathname === "/api/klines") {
      const sym = (url.searchParams.get("symbol") || "").toUpperCase();
      const ivKey = url.searchParams.get("interval") || "1h";
      const limit = Math.min(Math.max(parseInt(url.searchParams.get("limit") || "500", 10) || 500, 60), 1000);
      if (!SYMBOLS[sym]) return json({ error: "رمز غير مدعوم" }, 400);
      if (!INTERVALS[ivKey]) return json({ error: "إطار زمني غير مدعوم" }, 400);

      const cache = caches.default;
      const cacheKey = new Request(url.toString(), { method: "GET" });
      const hit = await cache.match(cacheKey);
      if (hit) return hit;
      try {
        const out = await klines(sym, ivKey, limit);
        const res = json({ symbol: sym, interval: ivKey, ...out }, 200, { "cache-control": "public, max-age=15" });
        ctx.waitUntil(cache.put(cacheKey, res.clone()));
        return res;
      } catch (e) {
        return json({ error: String(e.message || e) }, 502);
      }
    }

    if (url.pathname === "/api/health") return json({ ok: true, time: Date.now() });

    return new Response(HTML, {
      headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache", "x-content-type-options": "nosniff" },
    });
  },
};
